// ============================================================================
// SMBus_apb: APB4 register wrapper around SMBus_top (generated by
// scripts/apb/gen_apb.py from scripts/apb/specs/SMBus.json; do not edit)
// ----------------------------------------------------------------------------
//  - APB4 slave, zero wait states (PREADY = PSEL & PENABLE), 32-bit data,
//    12-bit byte address; PSLVERR on an unmapped or misaligned access.
//  - PSTRB byte lanes apply to every writable register.
//  - The core runs on PCLK/PRESETN; protocol pins pass through unchanged.
//  - Register map: docs/ip/SMBus.md
// ============================================================================
module SMBus_apb #(
  parameter logic [6:0] ADDR = 7'h5A,
  parameter int FILT = 3,
  parameter int HOLD = 4,
  parameter int STRETCH = 8,
  parameter int TIMEOUT = 2500000
) (
  input  logic        PCLK,
  input  logic        PRESETN,
  input  logic        PSEL,
  input  logic        PENABLE,
  input  logic        PWRITE,
  input  logic [11:0] PADDR,
  input  logic [31:0] PWDATA,
  input  logic [3:0]  PSTRB,
  output logic [31:0] PRDATA,
  output logic        PREADY,
  output logic        PSLVERR,
  output logic        irq,
  input logic scl,
  input logic sda,
  output logic scl_o,
  output logic sda_o,
  output logic smbalert_n
);
  localparam logic [31:0] ID_VALUE = 32'h53420100;

  // ---------------- APB decode ----------------
  wire        acc     = PSEL & PENABLE;
  wire        wr      = acc & PWRITE;
  wire        rd      = acc & ~PWRITE;
  wire [31:0] wmask   = {{8{PSTRB[3]}}, {8{PSTRB[2]}}, {8{PSTRB[1]}}, {8{PSTRB[0]}}};
  logic [8:0] hit;
  always_comb begin
    hit = '0;
    if (PADDR[1:0] == 2'b00 && PADDR[11:2] < 10'd9) hit[PADDR[11:2]] = 1'b1;
  end
  assign PREADY  = acc;
  assign PSLVERR = acc & ~|hit;

  // ---------------- core ----------------
  logic [7:0]    c_operation;
  logic [7:0]    c_on_off_config;
  logic [15:0]   c_vout_command;
  logic [15:0]   c_read_vout;
  logic          c_vout_ov;
  logic          c_irq_cml;
  logic          c_irq_upd;
  logic          c_irq_to;
  SMBus_top #(.ADDR(ADDR), .FILT(FILT), .HOLD(HOLD), .STRETCH(STRETCH), .TIMEOUT(TIMEOUT)) u_core (
    .clk(PCLK),
    .rst_n(PRESETN),
    .scl(scl),
    .sda(sda),
    .scl_o(scl_o),
    .sda_o(sda_o),
    .smbalert_n(smbalert_n),
    .operation(c_operation),
    .on_off_config(c_on_off_config),
    .vout_command(c_vout_command),
    .read_vout(c_read_vout),
    .vout_ov(c_vout_ov),
    .irq_cml(c_irq_cml),
    .irq_upd(c_irq_upd),
    .irq_to(c_irq_to)
  );

  // ---------------- registers ----------------
  logic [2:0] irq_status, irq_enable, irq_set;
  logic [31:0] scratch;
  logic [15:0] r_TELEMETRY;   // 12'h01C TELEMETRY
  logic [0:0] p_FAULT;   // 12'h020 FAULT (pulses)

  always_ff @(posedge PCLK or negedge PRESETN) begin
    if (!PRESETN) begin
      irq_status <= '0; irq_enable <= '0; scratch <= '0;
      r_TELEMETRY <= 16'h0;
      p_FAULT <= '0;
    end else begin
      irq_status <= (irq_status & ~((wr && hit[1]) ? PWDATA[2:0] & wmask[2:0] : '0)) | irq_set;
      if (wr && hit[2]) irq_enable <= (irq_enable & ~wmask[2:0]) | (PWDATA[2:0] & wmask[2:0]);
      if (wr && hit[4]) scratch <= (scratch & ~wmask) | (PWDATA & wmask);
      if (wr && hit[7]) r_TELEMETRY <= (r_TELEMETRY & ~wmask[15:0]) | (PWDATA[15:0] & wmask[15:0]);
      p_FAULT <= (wr && hit[8]) ? PWDATA[0:0] & wmask[0:0] : '0;
    end
  end

  // ---------------- core inputs ----------------
  assign c_read_vout = r_TELEMETRY[15:0];
  assign c_vout_ov = p_FAULT;

  // ---------------- interrupts and flags ----------------
  always_comb begin
    irq_set = '0;
    irq_set[0] = c_irq_cml;
    irq_set[1] = c_irq_upd;
    irq_set[2] = c_irq_to;
  end
  assign irq = |(irq_status & irq_enable);

  // ---------------- read mux ----------------
  logic [31:0] apb_rdata;
  always_comb begin
    apb_rdata = '0;
    case (PADDR[11:2])
      10'd0: apb_rdata = ID_VALUE;
      10'd1: apb_rdata = 32'(irq_status);
      10'd2: apb_rdata = 32'(irq_enable);
      10'd4: apb_rdata = scratch;
      10'd5: apb_rdata = 32'({c_vout_command});
      10'd6: apb_rdata = 32'({c_on_off_config, c_operation});
      10'd7: apb_rdata = 32'(r_TELEMETRY);
      default: apb_rdata = '0;
    endcase
  end
  assign PRDATA = (rd && |hit) ? apb_rdata : '0;
endmodule
